def calcular_frete(subtotal, distancia_km):
    """Frete grátis a partir de R$ 200; senão R$ 15 fixos mais R$ 0,50 por km acima de 10 km."""
    if subtotal > 200:
        return 0.0
    extra = max(0, distancia_km - 10) * 0.5
    return round(15 + extra, 2)

